export async function insertMember(
  orgId: OrgId,
  userId: UserId,
  role: Role,
  invitedBy: UserId | null,
): Promise<Member> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(members)
    .values({
      id: newId(),
      orgId,
      userId,
      role,
      status: "active",
      invitedBy,
      joinedAt: stamp,
      lastSeenAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMember(row);
}

export async function updateMemberRole(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
): Promise<Member> {
  const current = await findMemberById(orgId, memberId);
  if (!current) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  assertNotArchived("Member", memberId, current);
  const row = getDb()
    .update(members)
    .set({ role, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

/**
 * Removal is a soft delete so the audit log keeps pointing at a real row.
 * `status` is left as it was: it records what the membership was, and
 * `archivedAt` alone says that it ended.
 */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  return getDb().transaction((tx) => {
    const current = tx.select().from(members)
      .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId))).get();
    if (!current) throw new Error(`Member ${memberId} not found in org ${orgId}`);
    assertNotArchived("Member", memberId, toMember(current));

    const patch = archivePatch();
    const row = tx.update(members).set(patch)
      .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
      .returning().get();

    tx.update(issues).set({ assigneeId: null, updatedAt: patch.updatedAt })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.assigneeId, current.userId))).run();
    tx.update(projects).set({ leadId: null, updatedAt: patch.updatedAt })
      .where(and(orgPredicate(projects.orgId, orgId), eq(projects.leadId, current.userId))).run();

    return toMember(row!);
  });
}

export async function touchLastSeen(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(members)
    .set({ lastSeenAt: at })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId),
      eq(members.status, "active"), liveMemberPredicate()))
    .run();
}
"use server";

/**
 * Accepts an invitation token and creates the membership.
 *
 * Owner D. Runs for a signed-in user who is *not yet* a member of the target
 * org, so there is no `Actor` to resolve and the action cannot use
 * `withAction()`. The seat quota is re-checked at acceptance time because the
 * organization may have filled up since the invitation was sent.
 *
 * Must call (do not reimplement): acceptInvitationTokenSchema, getPlanLimits
 */

import { PlanLimitError, UnauthorizedActionError } from "@/actions/_lib/action-errors";
import { getPlanLimits } from "@/config/plan-limits";
import { toActionResult } from "@/lib/errors";
import { getSessionPrincipal } from "@/lib/session";
import { acceptInvitationTokenSchema } from "@/schemas/invitation";
import { acceptInvitation } from "@/server/services/invitation-service";
import { resolveActor } from "@/server/services/member-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Member } from "@/types/member";

export async function acceptInvitationAction(raw: unknown): Promise<ActionResult<Member>> {
  const parsed = acceptInvitationTokenSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const principal = await getSessionPrincipal();
    if (principal === null) {
      throw new UnauthorizedActionError("Sign in before accepting an invitation.");
    }

    const member = await acceptInvitation(principal.userId, parsed.data);
    await assertSeatAvailable(member);

    return { ok: true, data: member, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}

/**
 * Confirms the newly created membership still fits the plan. Reading usage
 * requires an actor inside the org, which only exists once the membership row
 * has been written — hence the check runs after `acceptInvitation`.
 */
async function assertSeatAvailable(member: Member): Promise<void> {
  const actor = await resolveActor(member.userId, member.orgId);
  if (actor === null) {
    throw new UnauthorizedActionError("That invitation is no longer valid.");
  }

  const summary = await getOrganizationSummary(actor, member.orgId);
  const limits = getPlanLimits(summary.organization.plan);
  if (summary.usage.seatsUsed > limits.seats) {
    throw new PlanLimitError("seats", limits.seats, summary.usage.seatsUsed);
  }
}
"use server";

/**
 * Creates an issue after the per-project quota check.
 *
 * Owner D. The quota is read from `@/config/plan-limits` rather than hard-coded
 * here — the plan of the owning organization decides `issuesPerProject`.
 *
 * Must call (do not reimplement): createIssueSchema, can, getPlanLimits,
 * getActor, toActionResult
 */

import { withAction } from "@/actions/_lib/with-action";
import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
import { getPlanLimits } from "@/config/plan-limits";
import { issueTag, orgTag, projectTag, revalidateTagged, CACHE_PROFILES } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { createIssueSchema, type CreateIssueInput } from "@/schemas/issue";
import { createIssue, listIssues } from "@/server/services/issue-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";

const run = withAction<typeof createIssueSchema, Issue>(
  createIssueSchema,
  async (raw, actor) => {
    const input = raw as CreateIssueInput;

    const allowed = can(actor, "issue:create", {
      kind: "issue",
      orgId: input.orgId,
      projectId: input.projectId,
      issueId: "" as Issue["id"],
      authorId: actor.userId,
      assigneeId: input.assigneeId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("issue:create");
    }

    await assertProjectHasRoom(actor, input);

    const issue = await createIssue(actor, input);

    revalidateTagged(
      [orgTag(input.orgId), projectTag(input.projectId), issueTag(issue.id)],
      CACHE_PROFILES.minutes,
    );
    return issue;
  },
  { revalidate: ["issues"], cacheProfile: "minutes" },
);

/**
 * Counts the issues already living in the project and compares them with the
 * plan's `issuesPerProject` ceiling. Archived issues still occupy the quota,
 * which is why the count deliberately includes them.
 */
async function assertProjectHasRoom(
  actor: Actor,
  input: CreateIssueInput,
): Promise<void> {
  const summary = await getOrganizationSummary(actor, input.orgId);
  const limits = getPlanLimits(summary.organization.plan);

  const existing = await listIssues(actor, {
    orgId: input.orgId,
    projectId: input.projectId,
    limit: 1,
    includeArchived: true,
  });

  if (existing.total >= limits.issuesPerProject) {
    throw new PlanLimitError("issuesPerProject", limits.issuesPerProject, existing.total);
  }
}

export async function createIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
  return run(raw);
}
"use server";

/**
 * Creates a project after the plan's project quota is checked.
 *
 * Owner D. Archived projects still occupy the quota, so the count deliberately
 * includes them — restoring a project must never be blocked by a limit the
 * restore itself would breach.
 *
 * Must call (do not reimplement): createProjectSchema, can, getPlanLimits,
 * getActor, toActionResult
 */

import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
import { PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { getPlanLimits } from "@/config/plan-limits";
import { CACHE_PROFILES, orgTag, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { createProjectSchema, type CreateProjectInput } from "@/schemas/project";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { createProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";

const run = withAction<typeof createProjectSchema, Project>(
  createProjectSchema,
  async (raw, actor) => {
    const input = raw as CreateProjectInput;

    const allowed = can(actor, "project:create", {
      kind: "project",
      orgId: input.orgId,
      projectId: PENDING_PROJECT_ID,
      visibility: input.visibility,
      leadId: input.leadId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:create");
    }

    const summary = await getOrganizationSummary(actor, input.orgId);
    const limits = getPlanLimits(summary.organization.plan);
    if (summary.usage.projectsUsed >= limits.projects) {
      throw new PlanLimitError("projects", limits.projects, summary.usage.projectsUsed);
    }

    const project = await createProject(actor, input);
    revalidateTagged(
      [orgTag(input.orgId), projectTag(project.id)],
      CACHE_PROFILES.minutes,
    );
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function createProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
/**
 * Explicit project membership for `private` projects.
 */
import { and, eq } from "drizzle-orm";
import { getDb, projectMembers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { OrgId, ProjectId, UserId } from "@/types/common";

export async function listProjectMemberIds(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .select({ userId: projectMembers.userId })
    .from(projectMembers)
    .where(
      and(
        orgPredicate(projectMembers.orgId, orgId),
        eq(projectMembers.projectId, projectId),
      ),
    )
    .all();
  return rows.map((row) => brandId<UserId>(row.userId));
}

/** Idempotent: re-adding an existing member is a no-op, not a conflict. */
export async function addProjectMember(
  orgId: OrgId,
  projectId: ProjectId,
  userId: UserId,
): Promise<void> {
  if (await isProjectMember(orgId, projectId, userId)) return;

  getDb()
    .insert(projectMembers)
    .values({
      orgId,
      projectId,
      userId,
      addedAt: toIsoTimestamp(new Date()),
    })
    .run();
}

export async function removeProjectMember(
  orgId: OrgId,
  projectId: ProjectId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(projectMembers)
    .where(
      and(
        orgPredicate(projectMembers.orgId, orgId),
        eq(projectMembers.projectId, projectId),
        eq(projectMembers.userId, userId),
      ),
    )
    .run();
}

export async function isProjectMember(
  orgId: OrgId,
  projectId: ProjectId,
  userId: UserId,
): Promise<boolean> {
  const row = getDb()
    .select({ userId: projectMembers.userId })
    .from(projectMembers)
    .where(
      and(
        orgPredicate(projectMembers.orgId, orgId),
        eq(projectMembers.projectId, projectId),
        eq(projectMembers.userId, userId),
      ),
    )
    .get();
  return row !== undefined;
}
